import { tokens, type StencilToken } from './scales'

const HEADER = `/*
 * Stencil scale tokens: space, block, layout, font size, line height, weight, reading, border, radius.
 * GENERATED by \`pnpm stencil:tokens\` from stencil/tokens/scales.ts. Do not edit by hand.
 *
 * Sizes are rem on a 10px root (\`--st-root-size\`), so one value scales the whole interface.
 * Space sizes what is inside a box, block sizes small boxes (icons, avatars), layout sizes
 * larger boxes. A stop is a multiple of its base x 100: \`--st-space-100\` is 8px, \`--st-space-200\`
 * is 16px, \`--st-layout-100\` is 64px.
 */
`

/** Renders the tokens as one `:root` block, grouped with a comment above each group. */
export function renderTokensCss(list: readonly StencilToken[] = tokens): string {
  const lines: string[] = [HEADER.trimEnd(), '', ':root {']
  let group = ''
  for (const token of list) {
    if (token.group !== group) {
      if (group !== '') lines.push('')
      lines.push(`  /* ${token.group} */`)
      group = token.group
    }
    lines.push(`  ${token.name}: ${token.css};`)
  }
  lines.push('}', '')
  return lines.join('\n')
}
